files.content:
.alert {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: calc(12px * var(--density)) calc(14px * var(--density));
  border-radius: var(--alert-radius, var(--r-md));
  border: var(--border-w) solid;
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  margin-top: 1px;
}

.content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.titleRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.title {
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.4;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: var(--r-2xs);
  background: rgba(var(--rgb-white), 0.75);
  box-shadow: inset 0 0 0 1px currentColor;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.body {
  font-size: var(--text-small);
  line-height: 1.55;
  color: var(--ink-body);
}

.body > * + * {
  margin-top: 6px;
}

.body ul {
  margin: 4px 0 0;
  padding-left: 18px;
}

.action {
  flex-shrink: 0;
  align-self: center;
}

.dismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  margin: -2px -4px 0 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  color: var(--ink-muted);
}

.dismiss:hover {
  background: rgba(var(--rgb-white), 0.6);
  color: var(--ink-body);
}

.dismiss:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

@media (max-width: 640px) {
  .alert {
    flex-wrap: wrap;
  }

  .action {
    flex-basis: 100%;
    padding-left: 28px;
  }
}

/* ── Tones ───────────────────────────────────────────────────────────── */

/* the reference tinted callout: two-stop brand wash with a little blur. */
.info {
  background: linear-gradient(135deg, rgba(var(--rgb-brand), 0.12), rgba(var(--rgb-brand-deep), 0.06));
  -webkit-backdrop-filter: var(--blur-callout);
  backdrop-filter: var(--blur-callout);
  border-color: var(--line-brand);
  color: var(--info-ink);
}

.success {
  background: var(--success-fill);
  border-color: var(--success-line);
  color: var(--success-ink);
}

.warning {
  background: var(--warning-fill);
  border-color: var(--warning-line);
  color: var(--warning-ink);
}

.danger {
  background: var(--danger-fill);
  border-color: var(--danger-line);
  color: var(--danger-ink);
}

/* Approved copy: the support neutral, the guide's quiet neutral. */
.legal {
  padding: 16px 18px;
  background: linear-gradient(135deg, rgba(var(--rgb-support), 0.42), rgba(var(--rgb-support), 0.22)), rgba(var(--rgb-white), 0.6);
  border-color: rgba(var(--rgb-support-deep), 0.36);
  color: var(--ink-heading);
}

.legal .body {
  font-size: var(--text-body);
  line-height: 1.6;
}

.jobCode {
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: var(--text-micro);
  letter-spacing: 0.06em;
  color: var(--ink-muted);
}

import type { ReactNode } from "react";
import { cx } from "../_internal/cx";
import { IconAlertCircle, IconAlertTriangle, IconCheckCircle, IconInfo, IconX } from "../Icon/Icon";
import styles from "./Alert.module.css";

export type AlertTone = "info" | "success" | "warning" | "danger" | "legal";

export type AlertProps = {
  tone: AlertTone;
  title?: ReactNode;
  children?: ReactNode;
  /** A button or link on the right (desktop) or below (mobile). */
  action?: ReactNode;
  icon?: ReactNode | false;
  /** Small uppercase tag before the title: "Cold chain", "Awaiting MLR". */
  badge?: ReactNode;
  /** legal only: the approval job code, set in mono under the copy. */
  jobCode?: string;
  /**
   * Announce on appearance. Use for banners that appear in response to an
   * action (a failed save), not for ones present on page load.
   */
  live?: boolean;
  onDismiss?: () => void;
  className?: string;
};

const ICONS: Record<Exclude<AlertTone, "legal">, ReactNode> = {
  info: <IconInfo size={17} />,
  success: <IconCheckCircle size={17} />,
  warning: <IconAlertTriangle size={17} />,
  danger: <IconAlertCircle size={17} />,
};

/**
 * Banners and callouts. info is the reference tinted callout (brand wash, small
 * blur); legal is a the support neutral box for approved copy that must be shown
 * verbatim, with its job code.
 */
export function Alert({ tone, title, children, action, icon, badge, jobCode, live, onDismiss, className }: AlertProps) {
  const glyph = icon === false ? null : (icon ?? (tone === "legal" ? null : ICONS[tone]));
  const role = live ? (tone === "danger" || tone === "warning" ? "alert" : "status") : undefined;

  return (
    <div data-slot="alert" role={role} className={cx(styles.alert, styles[tone], className)}>
      {glyph ? (
        <span className={styles.icon} aria-hidden="true">
          {glyph}
        </span>
      ) : null}
      <div className={styles.content}>
        {badge || title ? (
          <p className={styles.titleRow}>
            {badge ? <span className={styles.badge}>{badge}</span> : null}
            {title ? <span className={styles.title}>{title}</span> : null}
          </p>
        ) : null}
        {children ? <div className={styles.body}>{children}</div> : null}
        {jobCode ? <p className={styles.jobCode}>{jobCode}</p> : null}
      </div>
      {action ? <div className={styles.action}>{action}</div> : null}
      {onDismiss ? (
        <button type="button" className={styles.dismiss} onClick={onDismiss} aria-label="Dismiss">
          <IconX size={14} />
        </button>
      ) : null}
    </div>
  );
}
